values ('8631', 'chalet-urbanizacion-privada-ecija', 'Chalet en urbanización privada de Écija', 'Parcela de 980 m² con piscina, placas fotovoltaicas y vivienda principal en una sola planta.', 'Chalet urbano situado en una urbanización privada de Écija. La propiedad ocupa una parcela aproximada de 980 m² y dispone de una vivienda principal de unos 130 m², además de construcciones auxiliares. Cuenta con cuatro dormitorios, cocina amueblada, salón, dos baños, zona de ocio y piscina. La instalación de placas fotovoltaicas ayuda a reducir el consumo energético.', 'venta', 'chalet', 255000, null, null, 'Écija', 'Sevilla', 'Urbanización privada', 'Écija', null, null, 4, 2, 130, 980, 'Planta baja', null, null, array['Exclusiva','Piscina','Placas fotovoltaicas','Parcela de 980 m²','Zona de ocio','Cocina amueblada']::text[], array['/public/images/8631-chalet-urbanizacion.jpeg','/public/images/chalet-8631-01.jpeg','/public/images/8631-chalet-03.jpeg','/public/images/8631-chalet-04.jpeg','/public/images/8631-chalet-05.jpeg']::text[], '/public/images/8631-chalet-urbanizacion.jpeg', 'https://inmobiliarianoguera.com/property/chalet-en-urbanizacion-privada-de-ecija-sevilla/', true, true, 'published', 'Mónica Pérez', '653 855 641', '2026-07-04T09:00:00.000Z')
