values ('8288', 'casa-local-diez-minutos-ecija', 'Casa con local a diez minutos de Écija', '180 m², cuatro dormitorios, cocina amueblada, lavadero y terraza en un entorno tranquilo.', 'Casa con local situada a unos diez minutos de Écija. Tiene una superficie aproximada de 180 m², cuatro dormitorios, un baño, cocina amueblada, zona de lavadero y una terraza amplia para disfrutar en familia. La vivienda se encuentra en buen estado de conservación y en un entorno tranquilo.', 'venta', 'casa', 129500, null, null, 'Entorno de Écija', 'Sevilla', 'A 10 minutos de Écija', 'Entorno de Écija', null, null, 4, 1, 180, null, 'Casa', null, null, array['Exclusiva','Renta libre','Local incluido','Terraza','Cocina amueblada','Zona tranquila']::text[], array['/public/images/8288-casa-local-entrada.jpeg','/public/images/8288-casa-local.jpeg','/public/images/8288-casa-local-03.jpeg','/public/images/8288-casa-local-04.jpeg']::text[], '/public/images/8288-casa-local-entrada.jpeg', 'https://inmobiliarianoguera.com/property/casa-a-diez-minutos-de-ecija-sevilla/', true, true, 'published', 'Mónica Pérez', '653 855 641', '2026-07-02T09:00:00.000Z')
