values ('8694', 'nave-oficina-apartamento-piscina-canada-rosal', 'Nave con oficina, apartamento y piscina', '230 m² de nave, altillo de 70 m², apartamento de 55 m² y patio privado con piscina.', 'Nave industrial situada en Cañada Rosal, con una superficie útil aproximada de 230 m². Integra oficina, aseo y un altillo de 70 m². Dentro del recinto se incluye además un apartamento de unos 55 m² con cocina-comedor y un patio privado con piscina. El conjunto está vallado y ofrece una solución flexible para actividad profesional y descanso.', 'venta', 'nave', 124000, null, null, 'Cañada Rosal', 'Sevilla', 'Cañada Rosal', 'Cañada Rosal, Sevilla', null, null, 0, 1, 230, null, 'Nave + altillo', null, null, array['Exclusiva','Oficina','Altillo de 70 m²','Apartamento de 55 m²','Piscina','Recinto vallado']::text[], array['/public/images/8694-nave-piscina.jpeg','/public/images/8694-nave-interior.jpeg','/public/images/8694-nave-03.jpeg']::text[], '/public/images/8694-nave-piscina.jpeg', 'https://inmobiliarianoguera.com/property/%f0%9f%94%91-nave-en-venta-en-canada-rosal%f0%9f%94%91/', true, true, 'published', 'Mónica Pérez', '653 855 641', '2026-06-29T09:00:00.000Z')
