values ('8688', 'atico-dos-terrazas-alcarrachela', 'Ático con dos terrazas en La Alcarrachela', '80 m², tres dormitorios, dos baños, ascensor, dos terrazas y garaje para dos vehículos.', 'Ático VPO en La Alcarrachela, situado en un edificio con ascensor. Dispone de unos 80 m², tres dormitorios y dos baños. Destaca por sus dos terrazas: una de aproximadamente 24 m² y otra de unos 110 m². Incluye plaza de aparcamiento con capacidad para dos vehículos.', 'venta', 'ático', 205000, null, null, 'Écija', 'Sevilla', 'La Alcarrachela', 'La Alcarrachela, Écija', null, null, 3, 2, 80, null, 'Ático con ascensor', null, null, array['Exclusiva','VPO','Ascensor','Terraza de 24 m²','Terraza de 110 m²','Garaje para dos vehículos']::text[], array['/public/images/8688-atico-terrazas.jpeg','/public/images/8688-atico-cocina.jpeg']::text[], '/public/images/8688-atico-terrazas.jpeg', 'https://inmobiliarianoguera.com/property/%f0%9f%93%8datico-con-dos-terrazas-en-la-alcarrachela-ecija%f0%9f%93%8d/', true, true, 'published', 'Mónica Pérez', '653 855 641', '2026-06-17T09:00:00.000Z')
