values ('8662', 'casa-alcarrachela-porche-sotano-patio', 'Casa en La Alcarrachela con porche y sótano', '200 m², cuatro dormitorios, tres baños, garaje, terrazas privadas y amplio patio.', 'Casa en La Alcarrachela con una superficie aproximada de 200 m². En la planta principal dispone de porche, dormitorio, salón, aseo y garaje. La primera planta incorpora dos habitaciones con terraza privada y un baño completo. El sótano reúne cocina con salón, dos dormitorios, baño, lavadero y un patio amplio.', 'venta', 'casa', 310000, null, null, 'Écija', 'Sevilla', 'La Alcarrachela', 'La Alcarrachela, Écija', null, null, 4, 3, 200, null, 'Tres niveles', null, null, array['Exclusiva','Renta libre','Porche','Sótano','Patio','Garaje','Terrazas privadas']::text[], array['/public/images/8662-casa-alcarrachela.jpeg','/public/images/8662-casa-alcarrachela-patio.jpeg']::text[], '/public/images/8662-casa-alcarrachela.jpeg', 'https://inmobiliarianoguera.com/property/casa-en-la-alcarrachela-ecija-sevilla/', true, true, 'published', 'Mónica Pérez', '653 855 641', '2026-05-14T09:00:00.000Z')
