values ('8691', 'atico-calle-merinos-ecija', 'Ático con terraza en la zona de Calle Merinos', '90 m², tres dormitorios, chimenea, aire acondicionado, trastero y una amplia terraza.', 'Ático de unos 90 m² en la zona de Calle Merinos, Écija. Se sitúa en una tercera planta sin ascensor y dispone de tres dormitorios, un baño, cocina, comedor, lavadero y trastero. La vivienda es exterior y suma aire acondicionado frío-calor, chimenea, armarios empotrados y una terraza amplia.', 'venta', 'ático', 185000, null, null, 'Écija', 'Sevilla', 'Calle Merinos', 'Zona Calle Merinos, Écija', null, null, 3, 1, 90, null, '3ª planta sin ascensor', null, null, array['Exclusiva','Renta libre','Amplia terraza','Chimenea','Aire acondicionado','Trastero']::text[], array['/public/images/8691-atico-merinos.jpeg','/public/images/8691-atico-merinos-porche.jpeg']::text[], '/public/images/8691-atico-merinos.jpeg', 'https://inmobiliarianoguera.com/property/atico-en-venta-en-zona-calle-merinos-ecija-sevilla/', false, true, 'published', 'Mónica Pérez', '653 855 641', '2026-06-25T09:00:00.000Z')
