values ('0453', 'parcela-rustica-casa-piscina-ecija', 'Parcela rústica con vivienda y piscina', '4.000 m² de terreno, casa de 150 m², tres dormitorios, dos baños, nave y zona de ocio.', 'Parcela rústica situada a unos diez minutos de Écija, con fácil acceso, suministro de luz y agua y varias construcciones. La vivienda tiene unos 150 m², tres dormitorios, dos baños, dos salones, dos cocinas, cochera y patios. En la zona exterior dispone de porche, barbacoa, piscina, nave de aperos de unos 100 m² y terreno cultivable con olivos.', 'venta', 'parcela_rustica', 195000, null, null, 'Entorno de Écija', 'Sevilla', 'A 10 minutos de Écija', 'Entorno de Écija', null, null, 3, 2, 150, 4000, 'Casa + nave', null, null, array['Exclusiva','Parcela rústica','Piscina','Nave de aperos','Luz y agua','Barbacoa','Olivar']::text[], array['/public/images/0453-parcela-piscina.jpeg']::text[], '/public/images/0453-parcela-piscina.jpeg', 'https://inmobiliarianoguera.com/property/%f0%9f%93%8d-parcela-rustica-a-10-minutos-de-ecija-sevilla-%f0%9f%93%8d/', false, true, 'published', 'Mónica Pérez', '653 855 641', '2026-06-17T08:00:00.000Z')
