values ('NOVAÉ', 'novae-nueva-urbanizacion-ecija', 'NOVAÉ · Nueva promoción de viviendas en Écija', 'Promoción exclusiva de 26 viviendas de obra nueva frente al centro comercial N4.', 'NOVAÉ es una promoción de 26 viviendas de obra nueva frente al centro comercial N4, en Écija. El proyecto se presenta con distribuciones modernas, espacios luminosos, materiales de calidad y soluciones de eficiencia energética. Los precios, tipologías y disponibilidad deben confirmarse directamente con la agencia.', 'venta', 'casa', 0, null, null, 'Écija', 'Sevilla', 'Entorno Centro Comercial N4', 'Écija', null, null, null, null, null, null, null, 2026, null, array['Obra nueva','26 viviendas','Promoción exclusiva','Diseño contemporáneo','Eficiencia energética']::text[], array['/public/images/novae-terraza.jpeg']::text[], '/public/images/novae-terraza.jpeg', 'https://inmobiliarianoguera.com/property/novae-nueva-urbanizacion-en-ecija/', false, true, 'published', 'Mónica Pérez', '653 855 641', '2026-05-01T09:00:00.000Z')
